def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    rows = {r for r, c in markers if c == 0 or c == w - 1}
    cols = {c for r, c in markers if r == 0 or r == h - 1}
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 2 and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            ys = [y for y, x in component]
            xs = [x for y, x in component]
            if (max(ys) - min(ys) == max(xs) - min(xs)) and any(y in rows or x in cols for y, x in component):
                for y, x in component:
                    out[y][x] = 1
    for r in rows:
        out[r] = [1] * w
    for c in cols:
        for r in range(h):
            out[r][c] = 1
    return out

